using System;
using System.Runtime.InteropServices;

Console.WriteLine($"IntPtr size: {IntPtr.Size * 8} bits");

// Approximate object overhead:
// 8 bytes object header (sync block + method table)
// + field sizes
// + alignment padding

// A class with no fields still has overhead
EmptyClass obj = new EmptyClass();
Console.WriteLine(
    $"Allocated {GC.GetAllocatedBytesForCurrentThread()} bytes");

class EmptyClass { }

static void PrintValue(object value)
{
    // 'value' is boxed if a value type is passed.
    // The GC will need to collect this allocation later.
    Console.WriteLine(value);
}

// This allocates:
PrintValue(42);          // boxes int → heap allocation

// This does not:
static void PrintValue<T>(T value)
{
    // No boxing — T remains a value type at runtime
    Console.WriteLine(value);
}
PrintValue(42);          // no allocation
